+      StretchDIBits(mc.Handle, 10, 10, 40, 40, 0, 0, 4, 4,
+        @pix, bmi, DIB_RGB_COLORS, SRCCOPY);
+    finally
+      mc.Free;
+    end;
+    result := RenderedEmf(mf);
+  finally
+    mf.Free;
